data: {"id":"chatcmpl-20261012135552532123967c955d568911YWHCH","created":1791813353,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_4b5d5ee9d4e0436d87a3803d","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"MCMC posterior sampler — Beta-Binomial model.\\n\\nModel:\\n  y | theta ~ Binomial(n=10, theta),   observed y = 7\\n  theta ~ Beta(alpha=2, beta=2)\\nPosterior (conjugate): theta | y ~ Beta(9, 5)\\n\\nSampler: adaptive random-walk Metropolis on phi = logit(theta) (unconstrained).\\nConfiguration: 4 chains x (2000 warmup + 2000 sampling), seed 12345.\\n\\nRun modes:\\n  python3 mcmc_posterior.py            # full configured run\\n  python3 mcmc_posterior.py --smoke    # reduced iterations, validates the setup\\n\\\"\\\"\\\"\\nimport argparse\\nimport hashlib\\nimport math\\nimport random\\nimport statistics\\n\\n# ------------------------- configuration -------------------------\\nCONFIG = {\\n    \\\"chains\\\": 4,\\n    \\\"warmup\\\": 2000,\\n    \\\"samples\\\": 2000,\\n    \\\"seed\\\": 12345,\\n    \\\"init_scale\\\": 1.0,      # overdispersed init: phi0 ~ N(0, 1) on logit scale\\n    \\\"init_step\\\": 1.0,       # initial proposal sd on logit scale\\n    \\\"target_accept\\\": 0.44,  # optimal acceptance for 1-D random walk Metropolis\\n    \\\"adapt_gamma\\\": 0.6,     # Robbins-Monro decay: gamma_t = t^(-0.6)\\n}\\n\\n# ------------------------- model constants -------------------------\\nALPHA_PRIOR, BETA_PRIOR = 2.0, 2.0\\nY_OBS, N_TRIALS = 7, 10\\nA_POST = ALPHA_PRIOR + Y_OBS          # 9\\nB_POST = BETA_PRIOR + N_TRIALS - Y_OBS  # 5\\n\\n\\ndef inv_logit(x: float) -> float:\\n    \\\"\\\"\\\"Numerically stable logistic function.\\\"\\\"\\\"\\n    if x >= 0.0:\\n        return 1.0 / (1.0 + math.exp(-x))\\n    e = math.exp(x)\\n    return e / (1.0 + e)\\n\\n\\ndef log_post_phi(phi: float) -> float:\\n    \\\"\\\"\\\"Log posterior density of phi = logit(theta), up to a constant.\\n\\n    p(theta) ∝ theta^(A_POST-1) (1-theta)^(B_POST-1)  [Beta(9,5) kernel]\\n    Jacobian dtheta/dphi = theta (1-theta)\\n    => p(phi) ∝ theta^A_POST (1-theta)^B_POST\\n    \\\"\\\"\\\"\\n    theta = inv_logit(phi)\\n    if theta <= 0.0 or theta >= 1.0:\\n        return -math.inf\\n    return A_POST * math.log(theta) + B_POST * math.log1p(-theta)\\n\\n\\ndef spawn_seed(base: int, chain: int) -> int:\\n    \\\"\\\"\\\"Deterministic, well-separated per-chain seeds from one base seed.\\\"\\\"\\\"\\n    digest = hashlib.sha256(f\\\"{base}:{chain}\\\".encode()).digest()\\n    return int.from_bytes(digest[:8], \\\"big\\\")\\n\\n\\ndef run_chain(chain_id: int, cfg: dict):\\n    \\\"\\\"\\\"Run one chain. Returns (post-warmup draws of theta, post-warmup acceptance rate).\\\"\\\"\\\"\\n    rng = random.Random(spawn_seed(cfg[\\\"seed\\\"], chain_id))\\n    phi = rng.gauss(0.0, cfg[\\\"init_scale\\\"])\\n    lp = log_post_phi(phi)\\n    if not math.isfinite(lp):\\n        phi = 0.0  # theta = 0.5, guaranteed interior\\n        lp = log_post_phi(phi)\\n\\n    step = cfg[\\\"init_step\\\"]\\n    log_step = math.log(step)\\n    target = cfg[\\\"target_accept\\\"]\\n    gamma_exp = cfg[\\\"adapt_gamma\\\"]\\n\\n    draws = []\\n    accepted_post = 0\\n    total = cfg[\\\"warmup\\\"] + cfg[\\\"samples\\\"]\\n\\n    for t in range(1, total + 1):\\n        # symmetric normal proposal on the unconstrained scale\\n        prop = phi + rng.gauss(0.0, step)\\n        lp_prop = log_post_phi(prop)\\n\\n        # Metropolis accept/reject (log-space, no overflow)\\n        log_r = lp_prop - lp\\n        accept = (lp_prop > -math.inf) and (log_r >= 0.0 or math.log(rng.random()) < log_r)\\n        if accept:\\n            phi, lp = prop, lp_prop\\n\\n        if t <= cfg[\\\"warmup\\\"]:\\n            # Robbins-Monro step-size adaptation toward the target acceptance\\n            # rate, using the actual acceptance probability (Andrieu & Thoms 2008)\\n            p_accept = 1.0 if (not math.isfinite(log_r) or log_r >= 0.0) else math.exp(max(log_r, -700.0))\\n            gamma_t = t ** (-gamma_exp)\\n            log_step += gamma_t * (p_accept - target)\\n            step = math.exp(log_step)\\n        else:\\n            if accept:\\n                accepted_post += 1\\n            draws.append(inv_logit(phi))\\n\\n    return draws, accepted_post / cfg[\\\"samples\\\"]\\n\\n\\ndef split_rhat(chains_draws):\\n    \\\"\\\"\\\"Split-R-hat (Gelman et al.) across chains.\\\"\\\"\\\"\\n    m = len(chains_draws)\\n    half = len(chains_draws[0]) // 2\\n    splits = [c[:half] for c in chains_draws] + [c[half:2 * half] for c in chains_draws]\\n    means = [statistics.mean(s) for s in splits]\\n    vars_ = [statistics.variance(s) for s in splits]\\n    grand = statistics.mean(means)\\n    b = half * statistics.variance(means)          # between-split variance\\n    w = statistics.mean(vars_)                     # within-split variance\\n    var_plus = (half - 1) / half * w + b / half\\n    return math.sqrt(var_plus / w) if w > 0 else float(\\\"nan\\\")\\n\\n\\ndef main():\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\\"--smoke\\\", action=\\\"store_true\\\", help=\\\"reduced run to validate configuration\\\")\\n    args = ap.parse_args()\\n\\n    cfg = dict(CONFIG)\\n    if args.smoke:\\n        cfg[\\\"warmup\\\"], cfg[\\\"samples\\\"] = 500, 500\\n\\n    all_draws = []\\n    print(f\\\"mode={'smoke' if args.smoke else 'full'}  chains={cfg['chains']}  \\\"\\n          f\\\"warmup={cfg['warmup']}  samples={cfg['samples']}  seed={cfg['seed']}\\\")\\n    for c in range(cfg[\\\"chains\\\"]):\\n        draws, acc = run_chain(c, cfg)\\n        all_draws.append(draws)\\n        print(f\\\"chain {c}: mean(theta)={statistics.mean(draws):.4f}  \\\"\\n              f\\\"sd(theta)={statistics.stdev(draws):.4f}  accept_rate={acc:.3f}\\\")\\n\\n    pooled = [x for d in all_draws for x in d]\\n    print(f\\\"pooled: mean={statistics.mean(pooled):.4f}  sd={statistics.stdev(pooled):.4f}\\\")\\n    print(f\\\"split-R-hat: {split_rhat(all_draws):.4f}\\\")\\n    print(f\\\"exact Beta(9,5): mean={A_POST/(A_POST+B_POST):.4f}  \\\"\\n          f\\\"sd={math.sqrt(A_POST*B_POST/((A_POST+B_POST)**2*(A_POST+B_POST+1))):.4f}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"path\":\"mcmc_posterior.py\"}"}}]}}]}

