data: {"id":"chatcmpl-20261012135820811610280c955d568tbVIh2Dq","created":1791813501,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_9152d5b05e73473b9691855f","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Posterior summaries + convergence diagnostics for the Beta-Binomial MCMC run.\\n\\nRe-runs the configured sampler (fully deterministic under seed 12345: 4 chains,\\n2000 warmup + 2000 sampling each) and computes:\\n  - posterior mean / sd / median\\n  - 95% equal-tailed credible interval (2.5% / 97.5% percentiles)\\n  - ESS (multi-chain, Stan-style autocorrelation estimate + Geyer initial\\n    monotone positive sequence truncation)\\n  - split-R-hat\\n  - MCSE of the mean\\n  - exact Beta(9,5) reference values (mean, sd, quantiles via the exact\\n    polynomial CDF — a,b integers make the CDF a polynomial)\\n\\\"\\\"\\\"\\nimport math\\nimport statistics\\n\\nfrom mcmc_posterior import CONFIG, run_chain, split_rhat, A_POST, B_POST\\n\\n# ---------- quantile, type 7 (linear interpolation, numpy/R default) ----------\\ndef quantile(sorted_x, p):\\n    n = len(sorted_x)\\n    h = (n - 1) * p\\n    lo = math.floor(h)\\n    hi = min(lo + 1, n - 1)\\n    return sorted_x[lo] + (h - lo) * (sorted_x[hi] - sorted_x[lo])\\n\\n# ---------- ESS: multi-chain, Stan-style ----------\\ndef autocov_up_to(x, max_lag):\\n    \\\"\\\"\\\"Biased (1/n) autocovariance estimates for lags 0..max_lag.\\\"\\\"\\\"\\n    n = len(x)\\n    mu = sum(x) / n\\n    xc = [v - mu for v in x]\\n    return [sum(xc[i] * xc[i + t] for i in range(n - t)) / n\\n            for t in range(max_lag + 1)]\\n\\ndef ess_multichain(chains):\\n    m = len(chains)\\n    n = min(len(c) for c in chains)\\n    chains = [c[:n] for c in chains]\\n    means = [statistics.mean(c) for c in chains]\\n    W = statistics.mean(statistics.variance(c) for c in chains)\\n    var_plus = (n - 1) / n * W + statistics.variance(means)\\n    if var_plus <= 0:\\n        return float(\\\"nan\\\")\\n\\n    max_lag = n - 1\\n    L = 64\\n    while True:\\n        L = min(L, max_lag)\\n        acovs = [autocov_up_to(c, L) for c in chains]\\n        mean_acov = [statistics.mean(a[t] for a in acovs) for t in range(L + 1)]\\n        rho = [1.0 - (W - mean_acov[t]) / var_plus for t in range(L + 1)]\\n        # Geyer initial positive sequence: paired sums P_k = rho_2k + rho_2k+1\\n        pairs = []\\n        negative = False\\n        K = (L + 1) // 2 - 1          # last k with 2k+1 <= L\\n        for k in range(K + 1):\\n            p = rho[2 * k] + rho[2 * k + 1]\\n            if p <= 0.0:\\n                negative = True\\n                break\\n            pairs.append(p)\\n        if negative or K >= max_lag // 2:\\n            break\\n        L *= 4\\n\\n    if not pairs:\\n        return float(m * n)  # no detectable autocorrelation\\n    # initial monotone sequence adjustment\\n    for k in range(1, len(pairs)):\\n        pairs[k] = min(pairs[k], pairs[k - 1])\\n    tau = max(-1.0 + 2.0 * sum(pairs), 1e-8)\\n    return m * n / tau\\n\\n# ---------- exact Beta(9,5) reference ----------\\ndef beta_9_5_cdf(x):\\n    \\\"\\\"\\\"Exact CDF: F(x) = 6435 * integral_0^x t^8 (1-t)^4 dt  (B(9,5) = 1/6435).\\\"\\\"\\\"\\n    if x <= 0.0:\\n        return 0.0\\n    if x >= 1.0:\\n        return 1.0\\n    poly = (x**9 / 9.0 - 0.4 * x**10 + (6.0 / 11.0) * x**11\\n            - x**12 / 3.0 + x**13 / 13.0)\\n    return 6435.0 * poly\\n\\ndef beta_9_5_quantile(p):\\n    lo, hi = 0.0, 1.0\\n    for _ in range(200):  # bisection to double precision\\n        mid = 0.5 * (lo + hi)\\n        if beta_9_5_cdf(mid) < p:\\n            lo = mid\\n        else:\\n            hi = mid\\n    return 0.5 * (lo + hi)\\n\\ndef main():\\n    cfg = dict(CONFIG)\\n    print(f\\\"Running configured sampler: chains={cfg['chains']}  \\\"\\n          f\\\"warmup={cfg['warmup']}  samples={cfg['samples']}  seed={cfg['seed']}\\\\n\\\")\\n\\n    chains = []\\n    for c in range(cfg[\\\"chains\\\"]):\\n        draws, acc = run_chain(c, cfg)\\n        chains.append(draws)\\n        print(f\\\"chain {c}: accept={acc:.3f}\\\")\\n\\n    pooled = sorted(x for c in chains for x in c)\\n    mean = statistics.mean(pooled)\\n    sd = statistics.stdev(pooled)\\n    q025, q50, q975 = (quantile(pooled, p) for p in (0.025, 0.50, 0.975))\\n    ess = ess_multichain(chains)\\n    mcse = sd / math.sqrt(ess)\\n    rhat = split_rhat(chains)\\n\\n    ex_mean = A_POST / (A_POST + B_POST)\\n    ex_sd = math.sqrt(A_POST * B_POST /\\n                      ((A_POST + B_POST) ** 2 * (A_POST + B_POST + 1)))\\n    ex_q025 = beta_9_5_quantile(0.025)\\n    ex_q975 = beta_9_5_quantile(0.975)\\n\\n    print(\\\"\\\\n================ POSTERIOR SUMMARY (theta) ================\\\")\\n    print(f\\\"{'quantity':<22}{'MCMC':>12}{'exact Beta(9,5)':>18}\\\")\\n    print(f\\\"{'mean':<22}{mean:>12.4f}{ex_mean:>18.4f}\\\")\\n    print(f\\\"{'sd':<22}{sd:>12.4f}{ex_sd:>18.4f}\\\")\\n    print(f\\\"{'2.5% quantile':<22}{q025:>12.4f}{ex_q025:>18.4f}\\\")\\n    print(f\\\"{'median':<22}{q50:>12.4f}{beta_9_5_quantile(0.5):>18.4f}\\\")\\n    print(f\\\"{'97.5% quantile':<22}{q975:>12.4f}{ex_q975:>18.4f}\\\")\\n    print(\\\"\\\\n====================== DIAGNOSTICS ======================\\\")\\n    print(f\\\"total draws (post-warmup): {len(pooled)}\\\")\\n    print(f\\\"ESS (multi-chain, Geyer):  {ess:.0f}  ({100*ess/len(pooled):.1f}% efficiency)\\\")\\n    print(f\\\"MCSE of mean:              {mcse:.5f}\\\")\\n    print(f\\\"split-R-hat:               {rhat:.4f}\\\")\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"path\":\"posterior_summary.py\"}"}}]}}]}

