data: {"id":"chatcmpl-20261012140048445744042c955d568zUxY2uQN","created":1791813649,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_4dc92e32c07c467784d70b5a","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Posterior predictive check for the Beta-Binomial model.\\n\\nPosterior:          theta | y ~ Beta(9, 5)\\nReplicated data:    y_rep | theta ~ Binomial(10, theta)\\nExact marginal:     y_rep ~ Beta-Binomial(10, a=9, b=5)\\n\\nTest statistic: T(y) = y (number of successes)\\np-value = Pr(T(y_rep) >= T(y_obs) | y) = Pr(y_rep >= 7 | y)\\n\\nSources of theta draws, cross-checked:\\n  (a) 1000 draws thinned from the 8000-draw MCMC posterior sample (seed 12345)\\n  (b) 1000 draws sampled directly from the exact Beta(9, 5) posterior\\n  (c) exact Beta-Binomial(10, 9, 5) tail probability (analytic reference)\\n\\\"\\\"\\\"\\nimport math\\nimport random\\nimport statistics\\n\\nfrom mcmc_posterior import CONFIG, run_chain\\n\\nN, Y_OBS, S = 10, 7, 1000\\nA_POST, B_POST = 9, 5\\n\\n\\ndef binomial_draw(rng, n, p):\\n    return sum(1 for _ in range(n) if rng.random() < p)\\n\\n\\ndef bb_pmf(k, n, a, b):\\n    \\\"\\\"\\\"Beta-Binomial pmf on the log scale (exact reference).\\\"\\\"\\\"\\n    logC = math.lgamma(n + 1) - math.lgamma(k + 1) - math.lgamma(n - k + 1)\\n    logB_num = math.lgamma(k + a) + math.lgamma(n - k + b) - math.lgamma(n + a + b)\\n    logB_den = math.lgamma(a) + math.lgamma(b) - math.lgamma(a + b)\\n    return math.exp(logC + logB_num - logB_den)\\n\\n\\ndef replicate(theta_draws, label, rng):\\n    y_rep = [binomial_draw(rng, N, th) for th in theta_draws]\\n    p_sim = sum(1 for y in y_rep if y >= Y_OBS) / S\\n    se = math.sqrt(p_sim * (1 - p_sim) / S)  # MC standard error of the proportion\\n    counts = {k: y_rep.count(k) for k in range(N + 1)}\\n    print(f\\\"\\\\n--- {label} ---\\\")\\n    print(f\\\"mean(y_rep) = {statistics.mean(y_rep):.3f}   sd(y_rep) = {statistics.stdev(y_rep):.3f}\\\")\\n    print(\\\"replicated counts vs exact Beta-Binomial pmf:\\\")\\n    exact = [bb_pmf(k, N, A_POST, B_POST) for k in range(N + 1)]\\n    for k in range(N + 1):\\n        bar = \\\"#\\\" * counts[k]\\n        print(f\\\"  y={k:2d}: {counts[k]:4d} ({counts[k]/S:.3f})   exact pmf={exact[k]:.3f}  {bar}\\\")\\n    print(f\\\"p-value  Pr(y_rep >= {Y_OBS}) = {p_sim:.3f}  (MC SE = {se:.3f})\\\")\\n    return p_sim, counts\\n\\n\\ndef main():\\n    # ---- (a) MCMC-based posterior draws: thin 8000 -> 1000 ----\\n    cfg = dict(CONFIG)\\n    chains = [run_chain(c, cfg)[0] for c in range(cfg[\\\"chains\\\"])]\\n    pooled = [x for c in chains for x in c]           # 8000 posterior theta draws\\n    thin = len(pooled) // S                           # 8\\n    theta_mcmc = pooled[::thin][:S]                   # 1000 thinned draws\\n    p_a, counts_a = replicate(theta_mcmc, f\\\"(a) MCMC posterior draws ({S} thinned from {len(pooled)})\\\",\\n                              random.Random(12345))\\n\\n    # ---- (b) direct draws from exact Beta(9,5) posterior ----\\n    rng_b = random.Random(98765)\\n    theta_exact = [rng_b.betavariate(A_POST, B_POST) for _ in range(S)]\\n    p_b, _ = replicate(theta_exact, \\\"(b) direct Beta(9,5) draws\\\", rng_b)\\n\\n    # ---- (c) exact analytic tail ----\\n    exact = [bb_pmf(k, N, A_POST, B_POST) for k in range(N + 1)]\\n    assert abs(sum(exact) - 1.0) < 1e-10, \\\"Beta-Binomial pmf must sum to 1\\\"\\n    p_c = sum(exact[k] for k in range(Y_OBS, N + 1))\\n    pred_mean = N * A_POST / (A_POST + B_POST)\\n    pred_var = (N * A_POST * B_POST * (N + A_POST + B_POST)\\n                / ((A_POST + B_POST) ** 2 * (A_POST + B_POST + 1)))\\n    print(\\\"\\\\n--- (c) exact Beta-Binomial(10, 9, 5) ---\\\")\\n    print(f\\\"predictive mean = {pred_mean:.3f}   predictive sd = {math.sqrt(pred_var):.3f}\\\")\\n    print(f\\\"p-value  Pr(y_rep >= {Y_OBS}) = {p_c:.4f}\\\")\\n\\n    print(\\\"\\\\n================ PPC SUMMARY ================\\\")\\n    print(f\\\"observed y = {Y_OBS} out of n = {N}\\\")\\n    print(f\\\"p-value (MCMC draws):   {p_a:.3f}\\\")\\n    print(f\\\"p-value (exact draws):  {p_b:.3f}\\\")\\n    print(f\\\"p-value (analytic):     {p_c:.4f}\\\")\\n    print(f\\\"Pr(y_rep <= {Y_OBS}) exact: {sum(exact[k] for k in range(Y_OBS + 1)):.4f}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"path\":\"ppc_posterior.py\"}"}}]}}]}

