data: {"id":"chatcmpl-20261012140538307791126c955d568QwjootEP","created":1791813939,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_87e3ca0557e34d60aec25be2","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Model comparison: prior Beta(2,2) vs Jeffreys prior Beta(0.5,0.5).\\n\\nLikelihood (shared): y=7 successes in n=10 trials.\\n\\nCriteria:\\n  1. WAIC / elpd_waic  -- from MCMC posterior draws (trial-level: 10 Bernoulli\\n     points, 7 successes + 3 failures), cross-checked with an exact analytic\\n     identity via trigamma functions:\\n        Var[log theta]   = psi'(a) - psi'(a+b)\\n        Var[log(1-theta)] = psi'(b) - psi'(a+b)\\n  2. Exact LOO (elpd_loo) -- closed form under conjugacy:\\n        p(y_i=1 | y_-i) = (alpha + #succ_-i) / (alpha + beta + n - 1)\\n        p(y_i=0 | y_-i) = (beta  + #fail_-i) / (alpha + beta + n - 1)\\n  3. Log marginal predictive density (log score for the whole dataset):\\n        log C(n,y) + log B(alpha+y, beta+n-y) - log B(alpha, beta)\\n     (equivalently the log Beta-Binomial pmf; its ratio is a Bayes factor\\n      under equal model priors)\\n\\\"\\\"\\\"\\nimport math\\nimport statistics\\n\\nimport mcmc_posterior as mp\\n\\nN, Y = 10, 7\\nMODELS = {\\n    \\\"A: Beta(2,2) prior\\\":  (2.0, 2.0),\\n    \\\"B: Jeffreys (0.5,0.5)\\\": (0.5, 0.5),\\n}\\n\\n\\ndef trigamma(x: float) -> float:\\n    \\\"\\\"\\\"psi'(x) via upward recurrence + asymptotic expansion.\\\"\\\"\\\"\\n    s = 0.0\\n    while x < 30.0:\\n        s += 1.0 / (x * x)\\n        x += 1.0\\n    inv = 1.0 / x\\n    i2 = inv * inv\\n    tail = (inv + 0.5 * i2 + i2 * inv / 6.0\\n            - i2 * i2 * inv / 30.0 + i2 * i2 * i2 * inv / 42.0)\\n    return tail + s\\n\\n\\ndef lbeta(a, b):\\n    return math.lgamma(a) + math.lgamma(b) - math.lgamma(a + b)\\n\\n\\ndef analytic_waic(alpha, beta, y=Y, n=N):\\n    \\\"\\\"\\\"Exact lppd, p_waic, elpd for trial-level Bernoulli points.\\\"\\\"\\\"\\n    a, b = alpha + y, beta + n - y          # posterior parameters\\n    lppd = y * math.log(a / (a + b)) + (n - y) * math.log(b / (a + b))\\n    v_log_t = trigamma(a) - trigamma(a + b)\\n    v_log_1mt = trigamma(b) - trigamma(a + b)\\n    p_waic = y * v_log_t + (n - y) * v_log_1mt\\n    return lppd, p_waic, lppd - p_waic\\n\\n\\ndef waic_from_draws(thetas, y=Y, n=N):\\n    \\\"\\\"\\\"WAIC from posterior draws (exchangeable trials -> 2 distinct points).\\\"\\\"\\\"\\n    log_t = [math.log(t) for t in thetas]\\n    log_1mt = [math.log1p(-t) for t in thetas]\\n    mean_t, mean_1mt = statistics.mean(thetas), statistics.mean(1.0 - t for t in thetas)\\n    lppd_s, lppd_f = math.log(mean_t), math.log(mean_1mt)\\n    pw_s, pw_f = statistics.variance(log_t), statistics.variance(log_1mt)\\n    lppd = y * lppd_s + (n - y) * lppd_f\\n    p_waic = y * pw_s + (n - y) * pw_f\\n    pointwise = [lppd_s - pw_s] * y + [lppd_f - pw_f] * (n - y)\\n    se = math.sqrt(len(pointwise) * statistics.variance(pointwise))\\n    return lppd, p_waic, lppd - p_waic, se\\n\\n\\ndef exact_loo(alpha, beta, y=Y, n=N):\\n    \\\"\\\"\\\"Exact leave-one-out elpd and its SE (conjugate closed form).\\\"\\\"\\\"\\n    e_s = math.log((alpha + (y - 1)) / (alpha + beta + n - 1))\\n    e_f = math.log((beta + (n - y - 1)) / (alpha + beta + n - 1))\\n    pointwise = [e_s] * y + [e_f] * (n - y)\\n    se = math.sqrt(n * statistics.variance(pointwise))\\n    return sum(pointwise), se, pointwise\\n\\n\\ndef log_marginal(alpha, beta, y=Y, n=N):\\n    logC = (math.lgamma(n + 1) - math.lgamma(y + 1) - math.lgamma(n - y + 1))\\n    return logC + lbeta(alpha + y, beta + n - y) - lbeta(alpha, beta)\\n\\n\\ndef posterior_draws(alpha_p, beta_p):\\n    \\\"\\\"\\\"Run the configured sampler; return pooled post-warmup theta draws.\\\"\\\"\\\"\\n    mp.A_POST, mp.B_POST = alpha_p + Y, beta_p + N - Y\\n    cfg = dict(mp.CONFIG)\\n    chains = [mp.run_chain(c, cfg)[0] for c in range(cfg[\\\"chains\\\"])]\\n    return [x for c in chains for x in c]\\n\\n\\ndef main():\\n    results = {}\\n    for label, (al, be) in MODELS.items():\\n        draws = posterior_draws(al, be)\\n        lppd_d, p_d, elpd_d, se_d = waic_from_draws(draws)\\n        lppd_a, p_a, elpd_a = analytic_waic(al, be)\\n        elpd_l, se_l, pw_l = exact_loo(al, be)\\n        lm = log_marginal(al, be)\\n        results[label] = dict(elpd_waic_d=elpd_d, se_waic_d=se_d,\\n                              lppd_d=lppd_d, p_d=p_d,\\n                              elpd_waic_a=elpd_a, p_a=p_a,\\n                              elpd_loo=elpd_l, se_loo=se_l, pw_loo=pw_l,\\n                              log_marg=lm)\\n        print(f\\\"--- {label}  (posterior Beta({al + Y:g},{be + N - Y:g}), \\\"\\n              f\\\"{len(draws)} draws) ---\\\")\\n        print(f\\\"  WAIC from draws:   lppd={lppd_d:.4f}  p_waic={p_d:.4f}  \\\"\\n              f\\\"elpd={elpd_d:.4f} (se {se_d:.3f})   WAIC(dev)={-2 * elpd_d:.3f}\\\")\\n        print(f\\\"  WAIC analytic:     lppd={lppd_a:.4f}  p_waic={p_a:.4f}  \\\"\\n              f\\\"elpd={elpd_a:.4f}   (draws-vs-exact delta \\\"\\n              f\\\"{abs(elpd_d - elpd_a):.4f})\\\")\\n        print(f\\\"  exact LOO:         elpd={elpd_l:.4f} (se {se_l:.3f})   \\\"\\n              f\\\"WAIC-LOO delta={elpd_d - elpd_l:+.4f}\\\")\\n        print(f\\\"  log marginal pd:   {lm:.4f}   => Pr(y=7|model)={math.exp(lm):.4f}\\\")\\n\\n    # ---- paired difference (A - B): positive => A preferred ----\\n    a, b = results[\\\"A: Beta(2,2) prior\\\"], results[\\\"B: Jeffreys (0.5,0.5)\\\"]\\n    pw_diff = [x - y for x, y in zip(a[\\\"pw_loo\\\"], b[\\\"pw_loo\\\"])]\\n    se_diff = math.sqrt(len(pw_diff) * statistics.variance(pw_diff))\\n    d_loo = a[\\\"elpd_loo\\\"] - b[\\\"elpd_loo\\\"]\\n    d_waic = a[\\\"elpd_waic_d\\\"] - b[\\\"elpd_waic_d\\\"]\\n    d_lm = a[\\\"log_marg\\\"] - b[\\\"log_marg\\\"]\\n\\n    print(\\\"\\\\n================= MODEL COMPARISON =================\\\")\\n    print(f\\\"{'criterion':<34}{'A: Beta(2,2)':>14}{'B: Jeffreys':>14}{'A-B':>9}\\\")\\n    print(f\\\"{'elpd_waic (draws)':<34}{a['elpd_waic_d']:>14.4f}{b['elpd_waic_d']:>14.4f}{d_waic:>9.4f}\\\")\\n    print(f\\\"{'elpd_waic (exact)':<34}{a['elpd_waic_a']:>14.4f}{b['elpd_waic_a']:>14.4f}\\\"\\n          f\\\"{a['elpd_waic_a'] - b['elpd_waic_a']:>9.4f}\\\")\\n    print(f\\\"{'p_waic (eff. params)':<34}{a['p_d']:>14.4f}{b['p_d']:>14.4f}\\\"\\n          f\\\"{a['p_d'] - b['p_d']:>9.4f}\\\")\\n    print(f\\\"{'elpd_loo (exact)':<34}{a['elpd_loo']:>14.4f}{b['elpd_loo']:>14.4f}{d_loo:>9.4f}\\\")\\n    print(f\\\"{'log marginal pred. density':<34}{a['log_marg']:>14.4f}{b['log_marg']:>14.4f}{d_lm:>9.4f}\\\")\\n    print(f\\\"{'WAIC on deviance scale (-2*elpd)':<34}{-2 * a['elpd_waic_d']:>14.3f}\\\"\\n          f\\\"{-2 * b['elpd_waic_d']:>14.3f}{-2 * d_waic:>9.3f}\\\")\\n    print(f\\\"\\\\nelpd_loo difference (A-B): {d_loo:+.4f}, SE(paired) = {se_diff:.4f}\\\"\\n          f\\\"  -> |d|/se = {abs(d_loo) / se_diff:.2f}\\\")\\n    print(f\\\"marginal-likelihood ratio Pr(y|A)/Pr(y|B) = exp({d_lm:.4f}) = {math.exp(d_lm):.3f}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"path\":\"model_comparison.py\"}"}}]}}]}

