data: {"id":"chatcmpl-20261012140943364355942c955d568vgFl0Ob3","created":1791814184,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_ba4582b0b0a54eccbf830d7c","index":0,"type":"function","function":{"name":"file_write","arguments":"{\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Decision-theoretic summaries under the preferred model (Beta(2,2) prior).\\n\\nPosterior: theta | y ~ Beta(9, 5),  y = 7, n = 10.\\n\\nQuantities:\\n  1. Pr(theta > 0.5 | y)\\n       exact: 1 - F(0.5) where F(0.5) = P(Bin(13, 0.5) >= 9) = 1093/8192\\n       (integer-parameter identity, validated against the polynomial CDF)\\n       MCMC: proportion of 8000 posterior draws > 0.5\\n  2. Squared error loss L(theta, a) = (theta - a)^2:\\n       - Bayes estimator:   a* = E[theta|y] = 9/14\\n       - expected loss at a: EL(a) = Var(theta|y) + (E[theta|y] - a)^2\\n       - minimum expected loss EL(a*) = Var(theta|y) = 3/196\\n       also evaluated at the MLE (0.7) and at 0.5 for comparison.\\n\\\"\\\"\\\"\\nimport math\\nimport statistics\\n\\nimport mcmc_posterior as mp\\n\\nA, B = 9.0, 5.0          # posterior Beta(9,5)\\nY, N = 7, 10\\n\\n\\ndef poly_cdf(x):\\n    \\\"\\\"\\\"Exact Beta(9,5) CDF (polynomial; B(9,5) = 1/6435).\\\"\\\"\\\"\\n    if x <= 0.0:\\n        return 0.0\\n    if x >= 1.0:\\n        return 1.0\\n    poly = (x**9 / 9.0 - 0.4 * x**10 + (6.0 / 11.0) * x**11\\n            - x**12 / 3.0 + x**13 / 13.0)\\n    return 6435.0 * poly\\n\\n\\ndef main():\\n    # ---------- 1. Pr(theta > 0.5) ----------\\n    # integer identity: F(0.5; 9, 5) = P(Bin(13, 0.5) >= 9)\\n    from fractions import Fraction\\n    binom = [1, 13, 78, 286, 715, 1287, 1716, 1716, 1287, 715, 286, 78, 13, 1]\\n    tail = sum(binom[k] for k in range(9, 14))          # k = 9..13\\n    p_le = Fraction(tail, 2**13)\\n    p_gt = 1 - p_le\\n    assert abs(float(p_le) - poly_cdf(0.5)) < 1e-12, \\\"identity vs polynomial CDF\\\"\\n\\n    # MCMC check under the preferred model\\n    cfg = dict(mp.CONFIG)\\n    chains = [mp.run_chain(c, cfg)[0] for c in range(cfg[\\\"chains\\\"])]\\n    pooled = [x for c in chains for x in c]\\n    p_gt_mcmc = sum(1 for t in pooled if t > 0.5) / len(pooled)\\n    se = math.sqrt(p_gt_mcmc * (1 - p_gt_mcmc) / len(pooled))\\n\\n    print(\\\"================ 1. Pr(theta > 0.5 | y)  [Beta(9,5)] ================\\\")\\n    print(f\\\"exact:   1 - {p_le} = {float(p_gt):.6f}\\\")\\n    print(f\\\"MCMC:    {p_gt_mcmc:.4f}  (MC SE {se:.4f}; delta {abs(p_gt_mcmc - float(p_gt)):.4f} = \\\"\\n          f\\\"{abs(p_gt_mcmc - float(p_gt)) / se:.1f} SE)\\\")\\n\\n    # ---------- 2. squared error loss ----------\\n    mean = A / (A + B)                                   # 9/14\\n    var = A * B / ((A + B) ** 2 * (A + B + 1))           # 3/196\\n    from fractions import Fraction as F\\n    mean_f, var_f = F(9, 14), F(3, 196)\\n    assert abs(float(mean_f) - mean) < 1e-15 and abs(float(var_f) - var) < 1e-15\\n\\n    def exp_loss(a):\\n        \\\"\\\"\\\"EL(a) = Var + (mean - a)^2  (law of total expectation).\\\"\\\"\\\"\\n        return var + (mean - a) ** 2\\n\\n    print(\\\"\\\\n====== 2. Squared error loss  L(theta,a) = (theta - a)^2  [Beta(9,5)] ======\\\")\\n    print(f\\\"Bayes estimator a* = E[theta|y] = 9/14 = {mean:.6f}\\\")\\n    print(f\\\"posterior variance Var(theta|y) = 3/196 = {var:.6f}\\\"\\n          f\\\"   (posterior sd = {math.sqrt(var):.6f})\\\")\\n    print(f\\\"\\\\nminimum expected loss  EL(a*) = {float(var_f):.6f}\\\")\\n    print(\\\"\\\\nexpected loss at alternative estimates (higher = worse):\\\")\\n    for a, label in [(9 / 14, \\\"a* = 9/14 = 0.6429 (posterior mean)\\\"),\\n                     (0.7, \\\"MLE  = 0.7000\\\"),\\n                     (0.5, \\\"0.5000 (prior mean / null value)\\\"),\\n                     (0.6, \\\"0.6000\\\")]:\\n        el = exp_loss(a)\\n        print(f\\\"  a = {a:.4f}:  EL = {el:.6f}   ({label})\\\")\\n\\n    # MCMC versions\\n    m_mean, m_var = statistics.mean(pooled), statistics.variance(pooled)\\n    a_star = m_mean\\n    mc_el = sum((t - a_star) ** 2 for t in pooled) / len(pooled)\\n    print(f\\\"\\\\nMCMC cross-check ({len(pooled)} draws):\\\")\\n    print(f\\\"  E[theta|y] = {m_mean:.4f}   Var(theta|y) = {m_var:.6f}\\\")\\n    print(f\\\"  EL at MCMC posterior mean = {mc_el:.6f}\\\")\\n\\n    print(\\\"\\\\n====================== REPORT ======================\\\")\\n    print(f\\\"Pr(theta > 0.5 | y)            = {float(p_gt):.4f}   (exact)\\\")\\n    print(f\\\"Bayes estimate (squared error) = 9/14 = {mean:.4f}\\\")\\n    print(f\\\"Expected loss at that estimate = posterior variance = 3/196 = {var:.4f}\\\")\\n    print(f\\\"  (posterior sd {math.sqrt(var):.4f} is the square root of the expected loss)\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"path\":\"posterior_decision.py\"}"}}]}}]}

